import{_ as o,o as i,c as d,a3 as t}from"./chunks/framework.BTQ4eCVb.js";const h=JSON.parse('{"title":"Tenant API v1 — Invoices","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — Invoices | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-invoices"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — Invoices | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-invoices"}]]},"headers":[],"relativePath":"api/tenant-v1-invoices.md","filePath":"api/tenant-v1-invoices.md","lastUpdated":1788479753000}'),s={name:"api/tenant-v1-invoices.md"};function c(a,e,n,r,l,p){return i(),d("div",null,[...e[0]||(e[0]=[t('<h1 id="tenant-api-v1-—-invoices" tabindex="-1">Tenant API v1 — Invoices <a class="header-anchor" href="#tenant-api-v1-—-invoices" aria-label="Permalink to &quot;Tenant API v1 — Invoices&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1</code></p><p>Middleware: <code>auth:tenant-api</code>, <code>tenant.user</code>, <code>not.suspended</code>, <code>verified</code>, <code>module:invoices</code>, plus permission middleware / policies.</p><blockquote><p><strong>Naming:</strong> the model is <code>CustomerInvoice</code> — a tenant&#39;s invoices to <em>its own</em> customers. Central&#39;s own platform-billing <code>Invoice</code>/<code>tenant-v1-...</code> endpoints for subscription invoices are unrelated.</p></blockquote><p>Assignee scoping: without <code>invoices.assign</code> (and not superadmin), list/stats/view/update/<strong>send</strong>/<strong>void</strong>/<strong>email</strong> only include invoices where <code>assigned_to</code> is the current user.</p><h2 id="stats" tabindex="-1">Stats <a class="header-anchor" href="#stats" aria-label="Permalink to &quot;Stats&quot;">​</a></h2><h3 id="get-invoices-stats" tabindex="-1">GET <code>/invoices/stats</code> <a class="header-anchor" href="#get-invoices-stats" aria-label="Permalink to &quot;GET `/invoices/stats`&quot;">​</a></h3><p>Same filters as list (minus pagination/sort). Response:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;total_invoices&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;my_invoices&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;draft&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;unpaid&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;paid&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;cancelled&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;overdue&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;outstanding_balance&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;scope&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;org | mine&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>overdue</code> / <code>outstanding_balance</code> only consider invoices with <code>status</code> = <code>unpaid</code> and (for <code>overdue</code>) <code>due_date</code> in the past with <code>balance_due &gt; 0</code>.</p><h2 id="invoices-crud" tabindex="-1">Invoices CRUD <a class="header-anchor" href="#invoices-crud" aria-label="Permalink to &quot;Invoices CRUD&quot;">​</a></h2><h3 id="get-invoices" tabindex="-1">GET <code>/invoices</code> <a class="header-anchor" href="#get-invoices" aria-label="Permalink to &quot;GET `/invoices`&quot;">​</a></h3><p>Query: <code>search</code> (matches <code>title</code> or <code>number</code>), <code>status</code>, <code>contact_id</code>, <code>company_id</code>, <code>assigned_to</code> (<code>unassigned</code> or user id), <code>my_invoices</code>, <code>overdue</code> (<code>true</code>), <code>trashed</code> (<code>true</code>|<code>only</code>), <code>sort</code>, <code>direction</code>, <code>page</code>, <code>per_page</code>.</p><p>List items include <code>status</code>, <code>currency</code>, <code>subtotal</code>/<code>discount_total</code>/<code>tax_total</code>/<code>total</code>/<code>amount_paid</code>/<code>amount_credited</code>/<code>balance_due</code>, <code>issue_date</code>/<code>due_date</code>, recurrence fields (<code>is_recurring</code>, <code>recurrence_frequency</code>, <code>recurrence_status</code>, <code>recurrence_next_issue_on</code>, <code>recurrence_ends_on</code>, <code>recurring_source_invoice_id</code> / <code>recurring_source</code>), <code>contact</code>/<code>company</code>/<code>quotation</code>/<code>estimate</code>/<code>contract</code> refs, assignee/creator refs, and <code>latest_note</code>. Query also accepts <code>recurring=true</code> (series roots only).</p><p>The SPA may show a <strong>Partial</strong> label when <code>status</code> is <code>unpaid</code>, <code>amount_paid &gt; 0</code>, and <code>balance_due &gt; 0</code>. This is UI-only — the API still returns <code>status: unpaid</code>; there is no <code>partial</code> enum value.</p><h3 id="post-invoices" tabindex="-1">POST <code>/invoices</code> <a class="header-anchor" href="#post-invoices" aria-label="Permalink to &quot;POST `/invoices`&quot;">​</a></h3><p>Body: <code>title</code> (required), <code>notes</code> (HTML memo, sanitized server-side), <code>terms_and_conditions</code> (HTML, sanitized server-side), <code>currency</code> (3-letter, default <code>USD</code>), <code>issue_date</code>, <code>due_date</code> (dates), <code>contact_id</code>, <code>company_id</code> (optional, module-entitlement + assignee-scope validated via <code>LinkableContact</code>/<code>LinkableCompany</code>), <code>quotation_id</code> (optional, tenant-scoped existence check only), <code>reseller_id</code> (optional; requires Resellers entitled — <code>LinkableReseller</code>), <code>assigned_to</code>, <code>is_recurring</code> (boolean), <code>recurrence_frequency</code> (<code>weekly</code>|<code>monthly</code>|<code>quarterly</code>|<code>semi_annually</code>|<code>yearly</code>, required when recurring), <code>recurrence_next_issue_on</code> (date, required when recurring; must be after <code>issue_date</code> or today if issue date is empty; the SPA auto-fills one frequency period from the issue date and the client may override it), <code>recurrence_ends_on</code> (optional date; must be on or after the next invoice date), <code>line_discount_type</code> (<code>none</code>|<code>percent</code>|<code>fixed</code>), <code>lines</code> (array of <code>{ product_id?, name, body?, quantity, unit_price, tax_rate, sort_order, discount_value }</code>). <code>product_id</code> is optional and requires the Products module, <code>products.view</code> (or superadmin), and an active non-trashed product (<code>LinkableProduct</code>). <code>body</code> is optional HTML line details. <code>discount_value</code> is required on a line when <code>line_discount_type</code> is not <code>none</code>. The server stores client-sent <code>name</code>/<code>body</code>/<code>unit_price</code> as-is (does not re-copy from the product catalog).</p><p><code>subtotal</code>, <code>discount_total</code>, <code>tax_total</code>, <code>total</code>, and <code>balance_due</code> are computed server-side from <code>lines</code> and document discount — do not send them. Tax is calculated after discounts. Status always starts at <code>draft</code>; <code>number</code> is auto-generated (<code>INV-00001</code>, configurable prefix).</p><h3 id="get-invoices-id" tabindex="-1">GET <code>/invoices/{id}</code> <a class="header-anchor" href="#get-invoices-id" aria-label="Permalink to &quot;GET `/invoices/{id}`&quot;">​</a></h3><p>Includes contact, company, quotation, estimate, contract, assignee, creator, lines (<code>product_id</code>, optional <code>product</code> <code>{id,sku,name}</code> when loaded, <code>name</code>, <code>body</code>, <code>discount_value</code>), document <code>line_discount_type</code> / <code>discount_total</code>, <code>notes</code>, <code>terms_and_conditions</code>, <code>payment_allocations</code> (when loaded: allocation <code>amount</code> + nested <code>customer_payment</code> <code>{id,uuid,number,status,method,reference,currency,paid_at}</code>), timeline activities, recurrence fields, and (for an active series root) <code>latest_unpaid_generated_invoice</code> <code>{ id, number, status }</code> when one exists. Embedded <code>notes</code> and timeline/domain <code>activities</code> are <strong>newest-first</strong> (<code>created_at</code> DESC, then <code>id</code> DESC).</p><h3 id="get-invoices-id-pdf" tabindex="-1">GET <code>/invoices/{id}/pdf</code> <a class="header-anchor" href="#get-invoices-id-pdf" aria-label="Permalink to &quot;GET `/invoices/{id}/pdf`&quot;">​</a></h3><p>Permission: <code>invoices.view</code> (assignee-scoped). Extra limiter <code>throttle:invoices-pdf</code> (<code>INVOICES_PDF_PER_MINUTE</code>, default 30/user; disabled in tests). Returns <code>application/pdf</code> attachment <code>{number}.pdf</code>. Body is cached by invoice id + <code>updated_at</code> (<code>INVOICES_PDF_CACHE_SECONDS</code>, default 300). 404 if the invoice is deleted.</p><p>PDF includes sanitized memo HTML, line items, subtotal/discount/tax/total, balance due, and — when posted payments exist — a <strong>Payments received</strong> table (date, payment number, method, reference, amount). Shows a <strong>Partial</strong> chip when unpaid with partial payments. Discount rows appear when <code>discount_total &gt; 0</code>.</p><h3 id="put-invoices-id" tabindex="-1">PUT <code>/invoices/{id}</code> <a class="header-anchor" href="#put-invoices-id" aria-label="Permalink to &quot;PUT `/invoices/{id}`&quot;">​</a></h3><p>Partial update of <strong>draft</strong> invoices only. Sending <code>lines</code> replaces the full line-item set and recalculates totals (including <code>line_discount_type</code> and per-line <code>discount_value</code>). Non-draft invoices return 422 on <code>status</code> (<code>Only draft invoices can be edited.</code>). Assignment after send uses <code>POST /invoices/{id}/assign</code>.</p><h3 id="delete-invoices-id" tabindex="-1">DELETE <code>/invoices/{id}</code> <a class="header-anchor" href="#delete-invoices-id" aria-label="Permalink to &quot;DELETE `/invoices/{id}`&quot;">​</a></h3><p>Soft delete. Permission: <code>invoices.delete</code>.</p><h3 id="post-invoices-id-restore" tabindex="-1">POST <code>/invoices/{id}/restore</code> <a class="header-anchor" href="#post-invoices-id-restore" aria-label="Permalink to &quot;POST `/invoices/{id}/restore`&quot;">​</a></h3><p>Permission: <code>invoices.restore</code>.</p><h3 id="delete-invoices-id-force" tabindex="-1">DELETE <code>/invoices/{id}/force</code> <a class="header-anchor" href="#delete-invoices-id-force" aria-label="Permalink to &quot;DELETE `/invoices/{id}/force`&quot;">​</a></h3><p>Permanently delete a soft-deleted invoice. Permission: <code>invoices.force.delete</code> (owner/superadmin only by default).</p><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h2><h3 id="post-invoices-id-assign" tabindex="-1">POST <code>/invoices/{id}/assign</code> <a class="header-anchor" href="#post-invoices-id-assign" aria-label="Permalink to &quot;POST `/invoices/{id}/assign`&quot;">​</a></h3><p><code>{ &quot;assigned_to&quot;: number|null }</code></p><p>Permission: <code>invoices.assign</code>.</p><h3 id="post-invoices-id-send" tabindex="-1">POST <code>/invoices/{id}/send</code> <a class="header-anchor" href="#post-invoices-id-send" aria-label="Permalink to &quot;POST `/invoices/{id}/send`&quot;">​</a></h3><p>Transitions <code>draft → unpaid</code>. Backfills <code>issue_date</code> to today if unset. Permission: <code>invoices.send</code> (assignee-scoped unless the actor has <code>invoices.assign</code> or is superadmin). <strong>Status-only</strong> — does not email the customer. Recurring drafts become an <strong>active</strong> series. <code>recurrence_next_issue_on</code> stays the date chosen on the draft when it is after the issue date; otherwise it becomes one frequency period after the issue date.</p><h3 id="post-invoices-id-email" tabindex="-1">POST <code>/invoices/{id}/email</code> <a class="header-anchor" href="#post-invoices-id-email" aria-label="Permalink to &quot;POST `/invoices/{id}/email`&quot;">​</a></h3><p><code>{ &quot;to&quot;?: string[], &quot;cc&quot;?: string[], &quot;bcc&quot;?: string[], &quot;subject&quot;: string, &quot;message&quot;: string, &quot;attach_pdf&quot;?: boolean }</code></p><p>Permission: <code>invoices.send</code> (assignee-scoped unless the actor has <code>invoices.assign</code> or is superadmin). Throttle: <code>billing-document-email</code> (10/min per user).</p><p>Requires the invoice to already be sent — allowed statuses: <code>unpaid</code>, <code>partial</code> (display-only; stored as <code>unpaid</code>), <code>paid</code>. Draft and <code>cancelled</code> return 422 on <code>status</code> (<code>Send the document before emailing.</code>).</p><p>When <code>to</code> is omitted, resolves the recipient from the linked contact email, then company email. If no address is found, returns 422 on <code>to</code>.</p><p>Queues a branded email via the tenant mailer (optional PDF attachment from <code>CustomerInvoicePdfService</code>). Records an <code>emailed</code> timeline entry and a tenant email log row (<code>notification_type</code>: <code>customer_invoice.emailed</code>).</p><h3 id="post-invoices-id-recurrence-stop" tabindex="-1">POST <code>/invoices/{id}/recurrence/stop</code> <a class="header-anchor" href="#post-invoices-id-recurrence-stop" aria-label="Permalink to &quot;POST `/invoices/{id}/recurrence/stop`&quot;">​</a></h3><p><code>{ &quot;void_latest_unpaid&quot;: boolean }</code> (optional, default false)</p><p>Permission: <code>invoices.update</code>. Only valid on the <strong>series root</strong> while <code>recurrence_status=active</code>. Sets status to <code>ended</code>. When <code>void_latest_unpaid</code> is true, also cancels the latest generated draft/unpaid occurrence with zero paid/credited (requires <code>invoices.void</code> on that occurrence). Does not cancel the original invoice or paid history.</p><h3 id="post-invoices-id-void" tabindex="-1">POST <code>/invoices/{id}/void</code> <a class="header-anchor" href="#post-invoices-id-void" aria-label="Permalink to &quot;POST `/invoices/{id}/void`&quot;">​</a></h3><p>Transitions <code>draft|unpaid → cancelled</code>. <strong>Ledger guard:</strong> rejected with a 422 on <code>status</code> (naming the invoice number) if <code>amount_paid &gt; 0</code> (void the posted payments first) or <code>amount_credited &gt; 0</code> (refund applied credit notes first). Permission: <code>invoices.void</code> (assignee-scoped unless the actor has <code>invoices.assign</code> or is superadmin).</p><h3 id="post-invoices-id-status" tabindex="-1">POST <code>/invoices/{id}/status</code> <a class="header-anchor" href="#post-invoices-id-status" aria-label="Permalink to &quot;POST `/invoices/{id}/status`&quot;">​</a></h3><p><code>{ &quot;status&quot;: &quot;draft&quot;|&quot;unpaid&quot;|&quot;paid&quot;|&quot;cancelled&quot; }</code></p><p>Authorization depends on the target status:</p><ul><li><code>unpaid</code> → <code>invoices.send</code></li><li><code>cancelled</code> → <code>invoices.void</code></li><li>other allowed transitions → <code>invoices.update</code></li></ul><p>Rejects disallowed transitions with a 422 validation error on <code>status</code>. <code>paid</code> transitions are allowed here for completeness, but in practice are driven by <a href="/api/tenant-v1-payments">Payments</a> posting/voiding rather than direct user action. Applying a <a href="/api/tenant-v1-credit-notes">Credit Note</a> credits <code>amount_credited</code>/<code>balance_due</code> and keeps or clears status via balance helpers. A <code>cancelled</code> target is routed through the same ledger guard as <code>POST /invoices/{id}/void</code> (see above) — it is not a bare enum transition. Records a <code>status_changed</code> timeline entry (plus a <code>voided</code> activity entry when cancelling).</p><h3 id="post-invoices-id-notes" tabindex="-1">POST <code>/invoices/{id}/notes</code> <a class="header-anchor" href="#post-invoices-id-notes" aria-label="Permalink to &quot;POST `/invoices/{id}/notes`&quot;">​</a></h3><p><code>{ &quot;body&quot;: string }</code></p><p>Permission: <code>invoices.update</code>.</p><h3 id="get-invoices-id-timeline" tabindex="-1">GET <code>/invoices/{id}/timeline</code> <a class="header-anchor" href="#get-invoices-id-timeline" aria-label="Permalink to &quot;GET `/invoices/{id}/timeline`&quot;">​</a></h3><p>Domain timeline entries (<code>created</code>, <code>updated</code>, <code>assigned</code>, <code>status_changed</code>, <code>note_added</code>, <code>voided</code>, <code>deleted</code>, <code>restored</code>, <code>recurrence_started</code>, <code>recurrence_stopped</code>, <code>recurrence_generated</code>, <code>emailed</code>).</p>',58)])])}const m=o(s,[["render",c]]);export{h as __pageData,m as default};
